USE `ticket_system`;

-- ---------- 修复1：票档超卖，已售截断到总库存（售罄） ----------
UPDATE `ticket_price` SET `sold_stock` = `total_stock`, `update_time` = NOW()
WHERE `sold_stock` > `total_stock`;

-- ---------- 修复2：活动已售票数与票档之和不一致时，以票档之和同步 ----------
UPDATE `activity` a SET a.`sold_tickets` = (
        SELECT COALESCE(SUM(tp.`sold_stock`), 0) FROM `ticket_price` tp
        WHERE tp.`activity_id` = a.`id` AND tp.`status` = 1),
    a.`update_time` = NOW()
WHERE EXISTS (SELECT 1 FROM `ticket_price` tp WHERE tp.`activity_id` = a.`id`)
  AND a.`sold_tickets` <> (
        SELECT COALESCE(SUM(tp.`sold_stock`), 0) FROM `ticket_price` tp
        WHERE tp.`activity_id` = a.`id` AND tp.`status` = 1);

-- ---------- 修复3：作废已取消/已过期/已退款订单下仍有效的电子票 ----------
UPDATE `electronic_ticket` t JOIN `orders` o ON o.`id` = t.`order_id`
SET t.`status` = 2, t.`update_time` = NOW()
WHERE o.`status` IN (2, 3, 5) AND t.`status` = 0;

